const LANGUAGE_ALIASES = {
    "c++": "cpp",
    "c#": "csharp",
    cs: "csharp",
    js: "javascript",
    jsx: "javascript",
    py: "python",
    rb: "ruby",
    rs: "rust",
    ts: "typescript",
    tsx: "typescript",
    vb: "vbnet",
};
const LEVEL_PRIORITY = {
    critical: 3,
    error: 3,
    high: 3,
    medium: 2,
    warning: 2,
    low: 1,
    note: 1,
    info: 1,
};
export function parseFindingAnnotations(raw) {
    if (!raw) {
        return [];
    }
    try {
        const value = typeof raw === "string" ? JSON.parse(raw) : raw;
        if (!Array.isArray(value)) {
            return [];
        }
        return value
            .filter((item) => typeof item === "object" && item !== null && Number(item.startLine) > 0)
            .map((item) => ({
            ...item,
            endLine: Number(item.endLine ?? item.startLine),
            startLine: Number(item.startLine),
        }))
            .sort((left, right) => left.startLine - right.startLine);
    }
    catch {
        return [];
    }
}
export function sourceLanguage(value) {
    const normalized = value.toLowerCase().replace(/^language_/, "");
    return LANGUAGE_ALIASES[normalized] ?? normalized;
}
export function findingsForLine(findings, line) {
    return findings.filter((finding) => line >= Number(finding.startLine) &&
        line <= Number(finding.endLine ?? finding.startLine));
}
export function findingsOverlappingRange(findings, startLine, endLine) {
    return findings.filter((finding) => {
        const findingEndLine = Number(finding.endLine ?? finding.startLine);
        return finding.startLine <= endLine && findingEndLine >= startLine;
    });
}
export function findingTone(level) {
    const normalized = level?.toLowerCase() ?? "note";
    if (["error", "high", "critical"].includes(normalized)) {
        return "error";
    }
    if (["warning", "medium"].includes(normalized)) {
        return "warning";
    }
    return "note";
}
export function strongestFindingTone(findings) {
    if (findings.length === 0) {
        return undefined;
    }
    return findingTone(findings.reduce((strongest, finding) => {
        const strongestPriority = LEVEL_PRIORITY[strongest.level?.toLowerCase() ?? "note"] ?? 1;
        const findingPriority = LEVEL_PRIORITY[finding.level?.toLowerCase() ?? "note"] ?? 1;
        return findingPriority > strongestPriority ? finding : strongest;
    }).level);
}
